class StorageWithoutPath(Storage):
    """Delegate to memory storage while exposing only the object-storage API."""

    def __init__(self) -> None:
        """Keep the test's backing bytes isolated from all filesystem storage."""
        self.backend = InMemoryStorage()

    def _open(self, name: str, mode: str = "rb") -> Any:
        """Open remote-like bytes through the public storage interface."""
        return self.backend.open(name, mode)

    def _save(self, name: str, content: Any) -> str:
        """Persist bytes without exposing the backing store's path methods."""
        return self.backend.save(name, content)

    def exists(self, name: str) -> bool:
        """Check whether the remote-like object exists."""
        return self.backend.exists(name)

    def size(self, name: str) -> int:
        """Return stored byte size without requiring a local path."""
        return self.backend.size(name)

    def delete(self, name: str) -> None:
        """Remove one remote-like object."""
        self.backend.delete(name)

    def url(self, name: str) -> str:
        """Expose a realistic public-media URL that production must never return."""
        return f"https://public-media.invalid/{name}"


def install_extraction_storage(test_case: TestCase) -> StorageWithoutPath:
    """Isolate source and result storage while retaining real storage operations."""
    storage = StorageWithoutPath()
    for model, field in ((FileNode, "content"), (FileExtraction, "result")):
        test_case.enterContext(
            patch.object(model._meta.get_field(field), "storage", storage)
        )
    return storage


def create_source(content: bytes = b"Uploaded text", name: str = "source.txt") -> FileNode:
    """Create one persisted uploaded file with real stored bytes."""
    return FileNode.objects.create(content=ContentFile(content, name=name), kind="FILE")


def request_for(user: Any) -> HttpRequest:
    """Construct the same authenticated request context used by worker checks."""
    request = HttpRequest()
    request.user = user
    return request


def store_document(job: FileExtraction, records: list[dict[str, Any]]) -> None:
    """Persist a successful parser document with a compact production manifest."""
    document = {"format": "txt", "records": records, "index": {}, "truncated": False}
    job.result.name = job.store_result(document)
    job.manifest = api.compact_manifest(document)
    job.status = FileExtraction.Status.SUCCEEDED
    job.save()


