    def valid_queued_job(self, job: FileExtraction) -> bool:
        """Check finite deadlines and avoid exposing storage locators in descriptions."""
        payload = job.describe()
        return (
            job.status == FileExtraction.Status.QUEUED
            and job.start_deadline < job.expires_at
            and payload["poll_after_seconds"] == 3
            and payload["content_is_untrusted"]
            and "result" not in payload
            and job.manifest == {}
        )

