    def completed_job(self) -> FileExtraction:
        """Create a completed job and remember the private object-storage key."""
        job = self.create_job()
        store_document(job, [{"id": 1, "section": "Text", "text": "Private bytes"}])
        self.result_name = job.result.name
        return job

    def expired_job(self) -> FileExtraction:
        """Create a result whose retention window has ended."""
        job = self.completed_job()
        job.expires_at = timezone.now() - timedelta(seconds=1)
        job.save(update_fields=["expires_at"])
        return job

    def stalled_queue(self) -> FileExtraction:
        """Create an unclaimed job after its queue start deadline."""
        return self.create_job(start_deadline=timezone.now() - timedelta(seconds=1))

    def stalled_worker(self) -> FileExtraction:
        """Create an abandoned worker claim beyond its hard execution window."""
        return self.create_job(
            status=FileExtraction.Status.RUNNING,
            started_at=timezone.now() - timedelta(seconds=151),
        )

    def refresh_job(self, job: FileExtraction) -> None:
        """Refresh lifecycle through the same path used by every status read."""
        job.refresh_lifecycle()
        job.refresh_from_db()

    def expired_result_removed(self, job: FileExtraction) -> bool:
        """Require terminal expiry to remove both content and summary previews."""
        return (
            job.status == FileExtraction.Status.EXPIRED
            and not job.result
            and not job.manifest
            and not self.storage.exists(self.result_name)
        )

    def queue_is_unavailable(self, job: FileExtraction) -> bool:
        """Expose a fixed queue timeout rather than remaining pending indefinitely."""
        return (
            job.status == FileExtraction.Status.UNAVAILABLE
            and job.error_code == "worker_start_timeout"
            and job.finished_at is not None
        )

    def worker_timed_out(self, job: FileExtraction) -> bool:
        """Expose a fixed execution timeout once the worker lease expires."""
        return (
            job.status == FileExtraction.Status.FAILED
            and job.error_code == "execution_timeout"
        )

    def deleted_result_removed(self, job: FileExtraction) -> bool:
        """Require the deletion signal to reclaim private result bytes."""
        return not FileExtraction.objects.filter(
            pk=job.pk
        ).exists() and not self.storage.exists(self.result_name)

    def test_authorization_rechecks_owner_active_user_and_live_source(self) -> None:
        """Deny all status/result paths after owner, active-user or source access changes."""
        job = self.completed_job()
        self.other.is_superuser = True
        with self.assertRaises(NotFound):
            FileExtraction.authorized(request_for(self.other), job.pk)
        self.owner.is_active = False
        with self.assertRaises(NotFound):
            job.get_results(self.request)
        self.owner.is_active = True
        with patch(
            "bloomerp.files.access.FileAccessManager.can_read_file_node",
            return_value=False,
        ):
            for operation in (job.get_results, job.read_result):
                with (
                    self.subTest(operation=operation.__name__),
                    self.assertRaises(NotFound),
                ):
                    operation(self.request)
        self.source.delete()
        with self.assertRaises(NotFound):
            job.get_results(self.request)

    def test_result_reads_use_storage_open_and_enforce_byte_limit(self) -> None:
        """Support nonlocal storage and fail closed on corrupted or oversized JSON."""
        job = self.completed_job()
        self.assertEqual(
            job.get_results(self.request)["records"][0]["text"], "Private bytes"
        )
        for raw in (
            b"invalid JSON",
            b"[]",
            b'{"records":{}}',
            b" " * (MAX_STORED_BYTES + 1),
        ):
            with self.subTest(size=len(raw)):
                job.result.save(f"{job.pk}.json", ContentFile(raw), save=False)
                job.status = FileExtraction.Status.SUCCEEDED
                job.save()
                payload = job.get_results(self.request)
                self.assertEqual(payload["status"], FileExtraction.Status.FAILED)
                self.assertEqual(payload["error_code"], "result_unavailable")
                self.assertNotIn("records", payload)

    def test_unicode_continuation_preserves_text_and_response_ceiling(self) -> None:
        """Follow signed cursors without missing Unicode or exceeding inline limits."""
        job = self.create_job()
        original = "漢字🙂 café\n" * 1200
        store_document(
            job,
            [
                {"id": 1, "section": "Text", "text": original},
                {"id": 2, "section": "Text", "text": "Tail"},
            ],
        )
        cursor = None
        chunks: list[str] = []
        for _ in range(20):
            payload = job.get_results(
                self.request, section="Text", cursor=cursor, limit=1
            )
            self.assertLessEqual(
                len(json.dumps(payload, ensure_ascii=True).encode()), MAX_RESPONSE_BYTES
            )
            chunks.extend(record["text"] for record in payload["records"])
            cursor = payload["next_cursor"]
            if cursor is None:
                break
        self.assertIsNone(cursor, "Continuation must terminate")
        self.assertEqual("".join(chunks), original + "Tail")
        self.assertFalse(payload["source_truncated"])

    def test_selection_and_cursor_are_bound_to_job_and_selectors(self) -> None:
        """Select page/section/sheet cells and reject tampering or reused selections."""
        job = self.create_job()
        store_document(
            job,
            [
                {"id": 1, "page": 1, "section": "Intro", "text": "Page one"},
                {"id": 2, "page": 2, "section": "Body", "text": "Page two"},
                {
                    "id": 3,
                    "sheet": "Data",
                    "row": 2,
                    "column": 2,
                    "cell": "B2",
                    "text": "Selected",
                },
                {
                    "id": 4,
                    "sheet": "Data",
                    "row": 3,
                    "column": 3,
                    "cell": "C3",
                    "text": "Outside",
                },
            ],
        )
        self.assertEqual(
            job.get_results(self.request, page=2, section="Body")["records"][0]["id"], 2
        )
        self.assertEqual(
            [
                record["id"]
                for record in job.get_results(
                    self.request, sheet="Data", cell_range="B2:B2"
                )["records"]
            ],
            [3],
        )
        cursor = job.get_results(self.request, limit=1)["next_cursor"]
        for arguments in (
            {"cursor": cursor, "page": 1},
            {"cursor": "tampered"},
            {"cell_range": "B2"},
            {"sheet": "Data", "cell_range": "XFE1"},
            {"limit": 101},
        ):
            with self.subTest(arguments=arguments), self.assertRaises(ValidationError):
                job.get_results(self.request, **arguments)
        other = self.completed_job()
        with self.assertRaises(ValidationError):
            other.get_results(self.request, cursor=cursor)
        invalid = signing.dumps(
            {"job": str(job.pk), "selection": [None] * 4, "position": -1, "offset": 0},
            salt="bloomerp.file-extraction",
        )
        with self.assertRaises(ValidationError):
            job.get_results(self.request, cursor=invalid)

    def test_cleanup_expired_batch_is_bounded_and_removes_only_expired_bytes(
        self,
    ) -> None:
        """Opportunistic cleanup reclaims one bounded batch without harming live jobs."""
        for _ in range(22):
            self.expired_job()
        live = self.completed_job()
        FileExtraction.cleanup_expired()
        self.assertEqual(
            FileExtraction.objects.filter(status=FileExtraction.Status.EXPIRED).count(),
            20,
        )
        self.assertTrue(self.storage.exists(live.result.name))
        FileExtraction.cleanup_expired()
        self.assertEqual(
            FileExtraction.objects.filter(status=FileExtraction.Status.EXPIRED).count(),
            22,
        )

    def test_worker_claim_is_idempotent_and_fences_expired_jobs(self) -> None:
        """Redelivery cannot run the parser twice or revive stale queued work."""
        job = self.create_job()
        document = {
            "format": "txt",
            "records": [{"id": 1, "text": "Result"}],
            "index": {},
        }
        with patch.object(api, "run_parser", return_value=document) as parser:
            api.execute_file_extraction.run(str(job.pk), str(self.owner.pk))
            api.execute_file_extraction.run(str(job.pk), str(self.owner.pk))
            api.execute_file_extraction.run(
                str(self.stalled_queue().pk), str(self.owner.pk)
            )
        parser.assert_called_once()
        job.refresh_from_db()
        self.assertEqual(job.status, FileExtraction.Status.SUCCEEDED)
        self.assertEqual(job.get_results(self.request)["records"][0]["text"], "Result")

    def test_worker_rechecks_access_after_parsing_and_discards_late_results(
        self,
    ) -> None:
        """Permission revocation and expiry during parsing cannot publish result bytes."""
        job = self.create_job()
        document = {"format": "txt", "records": [{"text": "Secret"}], "index": {}}
        with (
            patch.object(api, "run_parser", return_value=document),
            patch(
                "bloomerp.files.access.FileAccessManager.can_read_file_node",
                side_effect=[True, False],
            ),
        ):
            api.execute_file_extraction.run(str(job.pk), str(self.owner.pk))
        job.refresh_from_db()
        self.assertEqual(job.status, FileExtraction.Status.CANCELLED)
        self.assertFalse(job.result)
        job = self.create_job()

        def expire_during_parse(source: FileNode, directory: str) -> dict[str, Any]:
            """Simulate expiry while the child process is doing authorized work."""
            FileExtraction.objects.filter(pk=job.pk).update(
                expires_at=timezone.now() - timedelta(seconds=1)
            )
            return document

        with patch.object(api, "run_parser", side_effect=expire_during_parse):
            api.execute_file_extraction.run(str(job.pk), str(self.owner.pk))
        job.refresh_from_db()
        self.assertEqual(job.status, FileExtraction.Status.EXPIRED)
        self.assertFalse(job.result)

    def test_worker_hides_exception_details_and_reports_provider_and_timeout(
        self,
    ) -> None:
        """Classify safe terminal errors without leaking parser paths or secrets."""
        for error, status, code in (
            (
                RuntimeError("/private/path secret"),
                FileExtraction.Status.FAILED,
                "extraction_failed",
            ),
            (
                subprocess.TimeoutExpired("private command", 120),
                FileExtraction.Status.FAILED,
                "execution_timeout",
            ),
            (
                api.ExtractionUnavailable(),
                FileExtraction.Status.UNAVAILABLE,
                "provider_unavailable",
            ),
            (
                ValueError("file_size_limit"),
                FileExtraction.Status.FAILED,
                "file_size_limit",
            ),
        ):
            with self.subTest(code=code):
                job = self.create_job()
                with patch.object(api, "run_parser", side_effect=error):
                    api.execute_file_extraction.run(str(job.pk), str(self.owner.pk))
                job.refresh_from_db()
                self.assertEqual((job.status, job.error_code), (status, code))
                self.assertFalse(job.result)

    def test_parser_runs_real_txt_and_xlsx_subprocesses_from_remote_storage(
        self,
    ) -> None:
        """Run the real bounded child for Unicode text and cached-value spreadsheets."""
        buffer = BytesIO()
        workbook = Workbook()
        worksheet = workbook.active
        worksheet.title = "Data"
        worksheet["A1"] = "Café 🙂"
        worksheet["B2"] = 42
        worksheet["C3"] = '=HYPERLINK("https://invalid.example", "do not fetch")'
        workbook.save(buffer)
        cases = (
            ("source.txt", "Café 🙂\nsecond line".encode(), "Café 🙂"),
            ("source.xlsx", buffer.getvalue(), "42"),
        )
        for name, content, expected in cases:
            with (
                self.subTest(name=name),
                tempfile.TemporaryDirectory() as directory,
                patch.object(api, "require_background_provider"),
            ):
                document = api.run_parser(create_source(content, name), directory)
                text = " ".join(record["text"] for record in document["records"])
                self.assertIn(expected, text)
                self.assertNotIn("HYPERLINK", text)
                self.assertLessEqual(
                    len(json.dumps(document).encode()), MAX_RESULT_BYTES
                )

    def test_parser_timeout_kills_process_group_and_bounds_wait(self) -> None:
        """A timed-out parser and its descendants are terminated without inline fallback."""
        process = Mock(pid=123456, returncode=0)
        process.wait.side_effect = [subprocess.TimeoutExpired("parser", 120), 0]
        with (
            tempfile.TemporaryDirectory() as directory,
            patch.object(api, "require_background_provider"),
            patch.object(api.subprocess, "Popen", return_value=process) as spawn,
            patch.object(api.os, "killpg") as kill,
            self.assertRaises(subprocess.TimeoutExpired),
        ):
            api.run_parser(self.source, directory)
        self.assertEqual(
            process.wait.call_args_list[0].kwargs, {"timeout": api.PARSER_SECONDS}
        )
        self.assertTrue(spawn.call_args.kwargs["start_new_session"])
        self.assertEqual(spawn.call_args.args[0][1], "-I")
        self.assertGreaterEqual(kill.call_count, 1)
        self.assertNotIn("HTTP_PROXY", spawn.call_args.kwargs["env"])

    def test_parser_source_and_result_byte_caps_are_enforced(self) -> None:
        """Bound downloaded source bytes and worker serialization before result storage."""
        with (
            tempfile.TemporaryDirectory() as directory,
            patch.object(api, "require_background_provider"),
            patch.object(api, "MAX_FILE_BYTES", 2),
            patch.object(api.subprocess, "Popen") as spawn,
        ):
            with self.assertRaisesRegex(ValueError, "file_size_limit"):
                api.run_parser(self.source, directory)
            spawn.assert_not_called()
        job = self.create_job()
        with (
            patch.object(
                api,
                "run_parser",
                return_value={"records": [{"id": 1, "text": "large" * 100}]},
            ),
            patch("bloomerp.models.files.file_extraction.MAX_RESULT_BYTES", 100),
        ):
            api.execute_file_extraction.run(str(job.pk), str(self.owner.pk))
        job.refresh_from_db()
        self.assertEqual(job.error_code, "result_size_limit")
        self.assertFalse(job.result)

    def test_private_storage_is_encrypted_and_not_auto_exposed(self) -> None:
        """Even a public-media backend stores ciphertext and has no generic CRUD routes."""
        from bloomerp.views.api.generic.base import AUTO_API_MODELS

        job = self.completed_job()
        with self.storage.open(job.result.name, "rb") as content:
            encrypted = content.read()
        self.assertNotIn(b"Private bytes", encrypted)
        self.assertNotIn(str(job.pk).encode(), encrypted)
        self.assertIn(b"Private bytes", job.decrypt_result(encrypted))
        self.assertNotIn(FileExtraction, AUTO_API_MODELS)
        self.assertTrue(FileExtraction.bloomerp_config.is_internal)
        self.assertFalse(FileExtraction.bloomerp_config.activity_log_settings.enabled)

    def test_malformed_authenticated_documents_fail_closed(self) -> None:
        """Reject malformed records after decryption without permitting oversized metadata."""
        from django.conf import settings

        job = self.completed_job()
        for records in (
            [None],
            [{"id": 1, "text": "safe", "section": {"nested": "data"}}],
            [{"id": 1, "text": "safe", "sheet": "x" * 32}],
        ):
            with self.subTest(records=records):
                raw = json.dumps({"records": records}).encode()
                encrypted = job.result_cipher(settings.SECRET_KEY).encrypt(raw)
                job.result.save("malformed.bin", ContentFile(encrypted), save=False)
                job.status = FileExtraction.Status.SUCCEEDED
                job.save()
                self.assertEqual(
                    job.get_results(self.request)["error_code"], "result_unavailable"
                )

    def test_unicode_manifest_and_cursor_always_leave_progress_budget(self) -> None:
        """Long non-BMP selectors and dense indexes cannot cause oversized or stuck responses."""
        generator = random.Random(7)
        section = "".join(
            chr(generator.randrange(0x10000, 0x10FFFF)) for _ in range(255)
        )
        text = "🙂" * 16000
        job = self.create_job()
        document = {
            "format": "xlsx",
            "truncated": False,
            "records": [{"id": 1, "text": text, "section": section}],
            "index": {
                "sections": [
                    {"section": section, "text": "🙂" * 255} for _ in range(16)
                ],
                "sheets": [
                    {"sheet": f"{index}" + "🙂" * 29, "text": "🙂" * 255}
                    for index in range(16)
                ],
            },
            "warnings": ["🙂" * 255] * 4,
            "truncation_reasons": ["🙂" * 255] * 12,
        }
        job.result.name = job.store_result(document)
        job.manifest = api.compact_manifest(document)
        manifest_bytes = len(json.dumps(job.manifest, ensure_ascii=True).encode())
        self.assertGreater(manifest_bytes, 6144)
        self.assertLessEqual(manifest_bytes, MAX_MANIFEST_BYTES)
        job.status = FileExtraction.Status.SUCCEEDED
        job.save()
        cursor = None
        received = ""
        for _ in range(40):
            payload = job.get_results(self.request, section=section, cursor=cursor)
            self.assertLessEqual(
                len(json.dumps(payload, ensure_ascii=True).encode()), MAX_RESPONSE_BYTES
            )
            self.assertTrue(payload["records"])
            received += "".join(record["text"] for record in payload["records"])
            if cursor:
                self.assertNotEqual(payload["next_cursor"], cursor)
            cursor = payload["next_cursor"]
            if cursor is None:
                break
        self.assertIsNone(cursor)
        self.assertEqual(received, text)

    def test_worker_reloads_user_before_result_publication(self) -> None:
        """A user disabled while parsing cannot retain a stale authenticated worker context."""
        job = self.create_job()

        def deactivate_during_parse(source: FileNode, directory: str) -> dict[str, Any]:
            """Revoke the account in the database while leaving the old object unchanged."""
            type(self.owner).objects.filter(pk=self.owner.pk).update(is_active=False)
            return {
                "format": "txt",
                "records": [{"id": 1, "text": "Secret"}],
                "index": {},
            }

        with patch.object(api, "run_parser", side_effect=deactivate_during_parse):
            api.execute_file_extraction.run(str(job.pk), str(self.owner.pk))
        job.refresh_from_db()
        self.assertEqual(job.status, FileExtraction.Status.CANCELLED)
        self.assertFalse(job.result)

    def test_expiry_storage_failure_never_exposes_content_and_cleanup_retries(
        self,
    ) -> None:
        """A failing object-store delete keeps a retry key while withholding all previews."""
        job = self.expired_job()
        name = job.result.name
        with patch.object(
            self.storage, "delete", side_effect=OSError("private bucket")
        ):
            payload = job.get_results(self.request)
        self.assertEqual(payload["status"], FileExtraction.Status.EXPIRED)
        self.assertEqual(payload["manifest"], {})
        self.assertNotIn("records", payload)
        self.assertTrue(self.storage.exists(name))
        FileExtraction.cleanup_expired()
        self.assertFalse(self.storage.exists(name))
        job.refresh_from_db()
        self.assertFalse(job.result)

    def test_stale_reader_cannot_replace_a_completed_worker_status(self) -> None:
        """Lifecycle timeout checks use conditional updates against a live worker race."""
        queued = self.stalled_queue()
        running = self.stalled_worker()
        for stale in (queued, running):
            with self.subTest(status=stale.status):
                FileExtraction.objects.filter(pk=stale.pk).update(
                    status=FileExtraction.Status.SUCCEEDED,
                    datetime_updated=timezone.now(),
                )
                stale.refresh_lifecycle()
                stale.refresh_from_db()
                self.assertEqual(stale.status, FileExtraction.Status.SUCCEEDED)
                self.assertEqual(stale.error_code, "")

    def test_worker_removes_ciphertext_when_final_claim_is_lost(self) -> None:
        """A lease lost during storage cannot leak an orphaned output object."""
        job = self.create_job()
        document = {
            "format": "txt",
            "records": [{"id": 1, "text": "Secret"}],
            "index": {},
        }
        stored_names: list[str] = []
        real_store = FileExtraction.store_result

        def expire_after_storage(
            instance: FileExtraction, result: dict[str, Any]
        ) -> str:
            """Expire the job immediately after its encrypted storage write succeeds."""
            name = real_store(instance, result)
            stored_names.append(name)
            FileExtraction.objects.filter(pk=instance.pk).update(
                status=FileExtraction.Status.EXPIRED
            )
            return name

        with (
            patch.object(api, "run_parser", return_value=document),
            patch.object(
                FileExtraction,
                "store_result",
                autospec=True,
                side_effect=expire_after_storage,
            ),
        ):
            api.execute_file_extraction.run(str(job.pk), str(self.owner.pk))
        job.refresh_from_db()
        self.assertEqual(job.status, FileExtraction.Status.EXPIRED)
        self.assertFalse(job.result)
        self.assertEqual(len(stored_names), 1)
        self.assertFalse(self.storage.exists(stored_names[0]))

    def test_existing_celery_worker_autodiscovery_registers_extraction(self) -> None:
        """The current worker loads the extraction task without a new service or worker app."""
        from celery import current_app

        from bloomerp.tasks import execute_file_extraction

        self.assertIs(execute_file_extraction, api.execute_file_extraction)
        registered = current_app.tasks["bloomerp.files.execute_extraction"]
        self.assertTrue(registered.acks_late)
        self.assertTrue(registered.reject_on_worker_lost)

    def test_new_migration_creates_and_reverses_schema_in_isolated_database(
        self,
    ) -> None:
        """Apply the new migration itself without rerunning the broken historical chain."""
        from importlib import import_module

        from django.apps import apps
        from django.db import connection
        from django.db.backends.sqlite3.base import DatabaseWrapper
        from django.db.migrations.state import ProjectState

        migration = import_module("bloomerp.migrations.0079_file_extraction")
        before = ProjectState.from_apps(apps)
        before.remove_model("bloomerp", "fileextraction")
        after = before.clone()
        operation = migration.Migration.operations[0]
        operation.state_forwards("bloomerp", after)
        database_settings = {
            **connection.settings_dict,
            "ENGINE": "django.db.backends.sqlite3",
            "NAME": ":memory:",
            "OPTIONS": {},
            "AUTOCOMMIT": True,
        }
        # Keep routing under the allowed alias; schema SQL uses this separate connection.
        isolated = DatabaseWrapper(database_settings, alias="default")
        self.addCleanup(isolated.close)
        with isolated.schema_editor(atomic=False) as editor:
            operation.database_forwards("bloomerp", editor, before, after)
        with isolated.cursor() as cursor:
            tables = isolated.introspection.table_names(cursor)
            self.assertIn("bloomerp_file_extraction", tables)
            fields = isolated.introspection.get_table_description(
                cursor, "bloomerp_file_extraction"
            )
            self.assertEqual(
                {field.name for field in fields},
                {field.column for field in FileExtraction._meta.local_fields},
            )
            constraints = isolated.introspection.get_constraints(
                cursor, "bloomerp_file_extraction"
            )
            self.assertIn("file_extract_status_exp_idx", constraints)
            self.assertEqual(
                constraints["file_extract_status_exp_idx"]["columns"],
                ["status", "expires_at"],
            )
        with isolated.schema_editor(atomic=False) as editor:
            operation.database_backwards("bloomerp", editor, after, before)
        self.assertNotIn(
            "bloomerp_file_extraction", isolated.introspection.table_names()
        )
